const nullMarker = "\x00null"

var sfGroup singleflight.Group

func GetUser(ctx context.Context, id string) (*User, error) {
    key := "user:" + id
    cached, err := rdb.Get(ctx, key).Bytes()
    switch {
    case err == nil:
        if string(cached) == nullMarker {
            return nil, ErrNotFound
        }
        var u User
        if err := json.Unmarshal(cached, &u); err != nil {
            return nil, fmt.Errorf("decode %s: %w", key, err)
        }
        return &u, nil
    case !errors.Is(err, redis.Nil):
        cacheOutages.Inc()
        return nil, fmt.Errorf("%w: %v", ErrCacheUnavailable, err)
    }

    val, err, _ := sfGroup.Do(key, func() (interface{}, error) {
        u, err := db.QueryUser(ctx, id)
        if errors.Is(err, sql.ErrNoRows) {
            if serr := rdb.Set(ctx, key, nullMarker, jitteredTTL(60*time.Second)).Err(); serr != nil {
                slog.WarnContext(ctx, "null-cache write failed", "key", key, "err", serr)
            }
            return nil, ErrNotFound
        }
        if err != nil {
            return nil, fmt.Errorf("query user %s: %w", id, err)
        }
        if serr := rdb.Set(ctx, key, marshal(u), jitteredTTL(30*time.Minute)).Err(); serr != nil {
            slog.WarnContext(ctx, "cache populate failed", "key", key, "err", serr)
        }
        return u, nil
    })
    if err != nil {
        return nil, err
    }
    u, ok := val.(*User)
    if !ok {
        return nil, fmt.Errorf("cache %s: unexpected type %T", key, val)
    }
    return u, nil
}
